#!/usr/bin/env python3
"""Writes the JSON-LD structured data into the website's pages, built from the pages themselves.

The FAQ entries come from the visible <details> blocks, so search engines never see answers that differ
from the page. Run it after changing a page; `--check` (CI) fails if a page is out of date.

    python3 .github/scripts/structured-data.py [--check]
"""
import html
import json
import re
import sys
from pathlib import Path

SITE = "https://tillackt.github.io/clipsody/"
DOWNLOAD = "https://github.com/tillackt/clipsody/releases/latest/download/Clipsody.dmg"
WEBSITE = Path(__file__).resolve().parents[2] / "website"
START = "<!-- structured-data:start (generated by .github/scripts/structured-data.py) -->"
END = "<!-- structured-data:end -->"
PLACEHOLDER = "<!--JSON-LD-->"
MODIFIED = "2026-10-30"

AUTHOR = {"@type": "Person", "name": "tillackt", "url": "https://github.com/tillackt"}

PAGES = {
    "index.html": {"kind": "app", "lang": "de",
                   "description": "Zwischenablage-Verlauf und Clipboard Manager für den Mac: merkt sich alle "
                                  "kopierten Texte, Bilder und Dateien, durchsuchbar und per Tastatur wieder eingefügt."},
    "en/index.html": {"kind": "app", "lang": "en",
                      "description": "Clipboard manager and clipboard history for the Mac: keeps every text, image "
                                     "and file you copy, searchable and pasted back from the keyboard."},
    "zwischenablage-verlauf-mac.html": {"kind": "guide", "lang": "de", "crumb": "Ratgeber"},
    "en/clipboard-history-mac.html": {"kind": "guide", "lang": "en", "crumb": "Guide"},
}


def text(fragment):
    """Visible text of an HTML fragment, whitespace collapsed."""
    return " ".join(html.unescape(re.sub(r"<[^>]+>", "", fragment)).split())


def page_url(name):
    return SITE + re.sub(r"(^|/)index\.html$", r"\1", name)


def faq(page):
    entries = re.findall(r"<details><summary>(.*?)</summary>\s*<p>(.*?)</p></details>", page, re.S)
    return {
        "@type": "FAQPage",
        "mainEntity": [{"@type": "Question", "name": text(question),
                        "acceptedAnswer": {"@type": "Answer", "text": text(answer)}}
                       for question, answer in entries],
    }


def graph(name, page, info):
    url = page_url(name)
    home = SITE if info["lang"] == "de" else SITE + "en/"
    items = []
    if info["kind"] == "app":
        items.append({
            "@type": "SoftwareApplication",
            "name": "Clipsody",
            "url": url,
            "description": info["description"],
            "applicationCategory": "UtilitiesApplication",
            "operatingSystem": "macOS 13 or later",
            "offers": {"@type": "Offer", "price": "0", "priceCurrency": "EUR"},
            "isAccessibleForFree": True,
            "downloadUrl": DOWNLOAD,
            "license": "https://www.gnu.org/licenses/gpl-3.0.html",
            "image": SITE + f"assets/og-{info['lang']}.png",
            "inLanguage": ["en", "de", "fr", "es", "it", "nl", "pl", "pt-BR"],
            "author": AUTHOR,
        })
    else:
        headline = text(re.search(r"<h1>(.*?)</h1>", page, re.S).group(1))
        description = re.search(r'<meta name="description" content="([^"]*)">', page).group(1)
        items.append({
            "@type": "Article",
            "headline": headline,
            "description": html.unescape(description),
            "inLanguage": info["lang"],
            "dateModified": MODIFIED,
            "mainEntityOfPage": url,
            "image": SITE + f"assets/og-{info['lang']}.png",
            "author": AUTHOR,
        })
        items.append({
            "@type": "BreadcrumbList",
            "itemListElement": [
                {"@type": "ListItem", "position": 1, "name": "Clipsody", "item": home},
                {"@type": "ListItem", "position": 2, "name": info["crumb"], "item": url},
            ],
        })
    items.append(faq(page))
    return {"@context": "https://schema.org", "@graph": items}


def render(name, page, info):
    data = json.dumps(graph(name, page, info), ensure_ascii=False, indent=2)
    # "</" inside the JSON would end the script element early.
    data = data.replace("</", "<\\/")
    block = f'{START}\n    <script type="application/ld+json">\n{data}\n    </script>\n    {END}'
    if PLACEHOLDER in page:
        return page.replace(PLACEHOLDER, block)
    return re.sub(re.escape(START) + r".*?" + re.escape(END), lambda _: block, page, flags=re.S)


def main():
    check = "--check" in sys.argv[1:]
    stale = []
    for name, info in PAGES.items():
        path = WEBSITE / name
        page = path.read_text(encoding="utf-8")
        if PLACEHOLDER not in page and START not in page:
            sys.exit(f"{name}: neither {PLACEHOLDER} nor the generated block found")
        updated = render(name, page, info)
        if updated != page:
            stale.append(name)
            if not check:
                path.write_text(updated, encoding="utf-8")
    if check and stale:
        sys.exit("Structured data out of date (run python3 .github/scripts/structured-data.py): " + ", ".join(stale))
    print("Structured data " + ("checked" if check else "written") + f" for {len(PAGES)} pages")


if __name__ == "__main__":
    main()
